#!/usr/bin/env node
/**
 * Generate the CLI's copy of the Code Explainer's analysis engine.
 *
 * The engine (outline, decision trees, call and data flow, entities, concepts) is written once, in
 * TypeScript, beside the VS Code panel that first used it. The CLI supports Node 20, which cannot
 * load TypeScript, so this transpiles those exact sources into plain modules under
 * `src/code-intelligence/generated/`. Comments are kept, so the generated code reads like its
 * source. `--check` fails when a generated file no longer matches its source; edit the TypeScript
 * and run this script, never the generated files.
 */
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import ts from 'typescript';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
export const CODE_INTELLIGENCE_SOURCES = Object.freeze([
  { from: 'apps/vscode/src/views/code-explainer-model.ts', to: 'src/code-intelligence/generated/code-explainer-model.mjs' },
  { from: 'apps/vscode/src/views/code-explainer-lenses.ts', to: 'src/code-intelligence/generated/code-explainer-lenses.mjs' }
]);

const RENAMES = new Map(CODE_INTELLIGENCE_SOURCES.map(({ from, to }) => [`./${path.basename(from)}`, `./${path.basename(to)}`]));

export function transpileCodeIntelligence(source, from) {
  const { outputText } = ts.transpileModule(source, {
    fileName: from,
    compilerOptions: {
      module: ts.ModuleKind.ESNext,
      target: ts.ScriptTarget.ES2022,
      removeComments: false,
      verbatimModuleSyntax: false,
      importsNotUsedAsValues: undefined
    }
  });
  let text = outputText;
  for (const [tsName, jsName] of RENAMES) text = text.split(`'${tsName}'`).join(`'${jsName}'`);
  return `// Generated by scripts/build-code-intelligence.mjs from ${from}. Do not edit.\n${text}`;
}

async function main() {
  const check = process.argv.includes('--check');
  const stale = [];
  for (const { from, to } of CODE_INTELLIGENCE_SOURCES) {
    const generated = transpileCodeIntelligence(await readFile(path.join(root, from), 'utf8'), from);
    const target = path.join(root, to);
    const current = await readFile(target, 'utf8').catch(() => null);
    if (current === generated) continue;
    if (check) { stale.push(to); continue; }
    await mkdir(path.dirname(target), { recursive: true });
    await writeFile(target, generated);
    console.log(`Wrote ${to}`);
  }
  if (stale.length) {
    console.error(`Generated code intelligence is stale: ${stale.join(', ')}. Run node scripts/build-code-intelligence.mjs.`);
    process.exitCode = 1;
  }
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) await main();
